// EntityLimits/LimitChangers: each finished entity of `civ` that is building `bld` (or
// roster row `tmpl`) adds `value` to the category's limit.
struct LimitChanger {
	uint8_t civ;
	uint8_t category;
	uint8_t bld;   // BLD_TYPE_COUNT when the changer is a unit
	uint16_t tmpl; // CIV_UNIT_TEMPLATE_NONE when it is a building
	int16_t value;
};

