// EntityLimits/LimitRemovers: the category's limit is lifted while the player is in
// `phase` (RequiredTechs phase_town/phase_city), has `tech`, and owns an entity of every
// RequiredClasses class (roster `flags`).
struct LimitRemover {
	uint8_t civ;
	uint8_t category;
	uint8_t phase;
	uint8_t tech;
	uint32_t flags;
};

